await check('fee fixture 20,150,000','document.querySelector("[data-total]").textContent.replace(/[^0-9]/g,"")==="20150000"');await fill('delivery',{service:'standard'});await check('fee reduced 120k → 65k, total 20,095,000','document.querySelector("[data-total]").textContent.replace(/[^0-9]/g,"")==="20095000"&&document.body.innerText.includes("Thay đổi phí giao cần xác nhận")');
