await E(`(()=>{const f=document.querySelector('form[data-form=place-order]');f.elements.changes.checked=true;f.elements.terms.checked=true;f.requestSubmit();f.requestSubmit();})()`);await delay();await check('double submit creates one order','location.pathname.endsWith("payment.html")&&JSON.parse(localStorage.getItem("pcmatch-demo-v2")).orders.length===1');
await fill('pay',{result:'failed'});await check('failed payment offers retry','document.body.innerText.includes("Thử thanh toán lại")');await fill('pay',{result:'unknown'});await check('unknown payment offers check','!!document.querySelector("[data-action=payment-check]")');await click('payment-check');
await E(`(()=>{const f=document.querySelector('form[data-form=pay]');f.elements.result.value='paid';f.requestSubmit();})()`);await new Promise(r=>setTimeout(r,350));await check('processing payment visible','document.body.innerText.includes("Đang xử lý thanh toán demo")');await delay();await check('success result for new order','document.body.innerText.includes("Thanh toán demo thành công")');
st=await state();const order=st.orders[0];await E('document.querySelector("a[href*=\\\"order.html\\\"]").click()');await delay();await check('correct order pending shop, never delivered','location.search.includes('+JSON.stringify(order.id)+')&&document.body.innerText.includes("Chờ shop xác nhận")&&!document.body.innerText.includes("Giao nhận: Đã giao")');
await nav('buyer/addresses.html');await delay();let addressId=(await state()).addresses[0].id;await nav('buyer/addresses.html?edit='+addressId);await delay();await fill('address',{name:'Người nhận đã sửa',phone:'0912345678',detail:'456 Đường Mới, Phường Demo',region:'HN'});await check('address edit preserves order snapshot','JSON.parse(localStorage.getItem("pcmatch-demo-v2")).orders[0].address.name==="Người mua"');await click('address-delete',addressId);await E('document.querySelector("#confirm [value=cancel]").click()');await check('cancel address deletion keeps address','JSON.parse(localStorage.getItem("pcmatch-demo-v2")).addresses.length===1');await click('address-delete',addressId);await confirm();await check('confirmed delete keeps historical address','JSON.parse(localStorage.getItem("pcmatch-demo-v2")).addresses.length===0&&JSON.parse(localStorage.getItem("pcmatch-demo-v2")).orders[0].address.name==="Người mua"');
await nav('buyer/orders.html');await delay();await fill('order-filter',{q:order.id,status:'paid'});await check('order search opens correct id','!!document.querySelector("a[href*=\\\"'+order.id+'\\\"]")');
for(const width of [360,768,1440]){await cdp('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:false});for(const p of ['cart','checkout','payment?id='+order.id,'order?id='+order.id,'addresses','orders']){const [r,q]=p.split('?');await nav('buyer/'+r+'.html'+(q?'?'+q:''));await delay();await check('responsive '+width+' '+r,'document.documentElement.scrollWidth<=innerWidth');}fs.writeFileSync('/tmp/pcmatch-purchase-'+width+'.png',Buffer.from((await cdp('Page.captureScreenshot',{format:'png'})).data,'base64'));}
